o:[{hi:'9:4',en:'9:4'},{hi:'2:3',en:'2:3'},{hi:'16:81',en:'16:81'},{hi:'4:9',en:'4:9'}],a:0,src:{hi:'RRB NTPC 2021',en:'RRB NTPC 2021'},
