o:[{hi:'₹1000',en:'₹1000'},{hi:'₹1050',en:'₹1050'},{hi:'₹977.5',en:'₹977.5'},{hi:'₹1100',en:'₹1100'}],a:0,src:{hi:'RRB NTPC 2019',en:'RRB NTPC 2019'},
