o:[{hi:'20%',en:'20%'},{hi:'25%',en:'25%'},{hi:'30%',en:'30%'},{hi:'15%',en:'15%'}],a:1,src:{hi:'RRB Group D 2022',en:'RRB Group D 2022'},
